using System.Net;
using System.Net.Http.Json;
using Xunit;

namespace TC1.RepairShop.IntegrationTests;

public class CustomerAuthEndpointTests : IClassFixture<ApiWebApplicationFactory>
{
    // Default password generated by Customer.Create: first 3 digits of the NationalId + capitalized first name.
    // FakeCustomerRepository.SeedCustomer is "Jane Doe" / "52998224725".
    private const string DefaultPassword = "529Jane";

    private readonly HttpClient _client;

    public CustomerAuthEndpointTests(ApiWebApplicationFactory factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task CustomerLogin_WithValidCredentials_ShouldReturnJwtToken()
    {
        var response = await _client.PostAsJsonAsync(
            "/api/auth/customer-login",
            new { nationalId = FakeCustomerRepository.SeedCustomer.NationalId, password = DefaultPassword });

        Assert.Equal(HttpStatusCode.OK, response.StatusCode);

        var body = await response.Content.ReadFromJsonAsync<LoginResponseDto>();
        Assert.False(string.IsNullOrWhiteSpace(body?.Token));
    }

    [Fact]
    public async Task CustomerLogin_WithInvalidPassword_ShouldReturn401()
    {
        var response = await _client.PostAsJsonAsync(
            "/api/auth/customer-login",
            new { nationalId = FakeCustomerRepository.SeedCustomer.NationalId, password = "wrong-password" });

        Assert.Equal(HttpStatusCode.Unauthorized, response.StatusCode);
    }

    [Fact]
    public async Task CustomerLogin_WithUnknownNationalId_ShouldReturn401()
    {
        var response = await _client.PostAsJsonAsync(
            "/api/auth/customer-login",
            new { nationalId = "00000000000", password = DefaultPassword });

        Assert.Equal(HttpStatusCode.Unauthorized, response.StatusCode);
    }

    [Fact]
    public async Task Customer_ShouldNotAccessStaffOnlyRoutes()
    {
        var loginResponse = await _client.PostAsJsonAsync(
            "/api/auth/customer-login",
            new { nationalId = FakeCustomerRepository.SeedCustomer.NationalId, password = DefaultPassword });
        var login = await loginResponse.Content.ReadFromJsonAsync<LoginResponseDto>();

        _client.DefaultRequestHeaders.Authorization =
            new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", login!.Token);

        var usersResponse = await _client.GetAsync("/api/users");
        Assert.Equal(HttpStatusCode.Forbidden, usersResponse.StatusCode);

        var customersResponse = await _client.GetAsync("/api/customers");
        Assert.Equal(HttpStatusCode.Forbidden, customersResponse.StatusCode);
    }

    [Fact]
    public async Task Customer_ShouldAccessMyQuotesRoute()
    {
        var loginResponse = await _client.PostAsJsonAsync(
            "/api/auth/customer-login",
            new { nationalId = FakeCustomerRepository.SeedCustomer.NationalId, password = DefaultPassword });
        var login = await loginResponse.Content.ReadFromJsonAsync<LoginResponseDto>();

        _client.DefaultRequestHeaders.Authorization =
            new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", login!.Token);

        var response = await _client.GetAsync("/api/customers/me/quotes");
        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
    }

    [Fact]
    public async Task Staff_ShouldNotAccessCustomerOnlyMyQuotesRoute()
    {
        var loginResponse = await _client.PostAsJsonAsync("/api/auth/login", new { username = "admin", password = "Admin@123" });
        var login = await loginResponse.Content.ReadFromJsonAsync<LoginResponseDto>();

        _client.DefaultRequestHeaders.Authorization =
            new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", login!.Token);

        var response = await _client.GetAsync("/api/customers/me/quotes");
        Assert.Equal(HttpStatusCode.Forbidden, response.StatusCode);
    }

    // Uses its own freshly-created customer (not the shared SeedCustomer) since it mutates the password.
    private async Task<string> CreateCustomerAndGetNationalIdAsync(string nationalId)
    {
        var staffLoginResponse = await _client.PostAsJsonAsync("/api/auth/login", new { username = "admin", password = "Admin@123" });
        var staffLogin = await staffLoginResponse.Content.ReadFromJsonAsync<LoginResponseDto>();

        var previousAuth = _client.DefaultRequestHeaders.Authorization;
        _client.DefaultRequestHeaders.Authorization =
            new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", staffLogin!.Token);

        await _client.PostAsJsonAsync(
            "/api/customers",
            new { name = "Password Test Customer", nationalId, phone = "11988887777", email = "pwtest@example.com" });

        _client.DefaultRequestHeaders.Authorization = previousAuth;
        return nationalId;
    }

    [Fact]
    public async Task ChangePassword_ThenLoginWithNewPassword_ShouldSucceed()
    {
        var nationalId = await CreateCustomerAndGetNationalIdAsync("57717791994");

        var loginResponse = await _client.PostAsJsonAsync(
            "/api/auth/customer-login",
            new { nationalId, password = "577Password" });
        var login = await loginResponse.Content.ReadFromJsonAsync<LoginResponseDto>();
        Assert.NotNull(login);

        _client.DefaultRequestHeaders.Authorization =
            new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", login!.Token);

        var changeResponse = await _client.PutAsJsonAsync(
            "/api/customers/me/password",
            new { currentPassword = "577Password", newPassword = "NewPassw0rd!" });
        Assert.Equal(HttpStatusCode.NoContent, changeResponse.StatusCode);

        _client.DefaultRequestHeaders.Authorization = null;
        var newLoginResponse = await _client.PostAsJsonAsync(
            "/api/auth/customer-login",
            new { nationalId, password = "NewPassw0rd!" });
        Assert.Equal(HttpStatusCode.OK, newLoginResponse.StatusCode);
    }

    [Fact]
    public async Task ChangePassword_WithWrongCurrentPassword_ShouldReturn400()
    {
        var nationalId = await CreateCustomerAndGetNationalIdAsync("96133641100");

        var loginResponse = await _client.PostAsJsonAsync(
            "/api/auth/customer-login",
            new { nationalId, password = "961Password" });
        var login = await loginResponse.Content.ReadFromJsonAsync<LoginResponseDto>();
        Assert.NotNull(login);

        _client.DefaultRequestHeaders.Authorization =
            new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", login!.Token);

        var changeResponse = await _client.PutAsJsonAsync(
            "/api/customers/me/password",
            new { currentPassword = "wrong-password", newPassword = "NewPassw0rd!" });

        Assert.Equal(HttpStatusCode.BadRequest, changeResponse.StatusCode);
    }

    private record LoginResponseDto(string Token);
}
